    const versions = registry[name];
    requireRecord(versions);
    const candidates = Object.keys(versions).map(text => ({
      text, tuple: parse(text), deps: requirements(versions[text]),
    }));
    candidates.sort(candidateOrder);
    catalogs.set(name, candidates);
  }
  const initial = requirements(root);
  const selected = new Map();
  const constraints = new Map();
  const trail = [];
  const queue = [];
  const choices = [];
  let cursor = 0;

  function rollback(trailMark) {
    while (trail.length > trailMark) {
      const name = trail.pop();
      const list = constraints.get(name);
      list.pop();
      if (list.length === 0) constraints.delete(name);
    }
  }

  function append(items) {
    const trailMark = trail.length;
    const queueMark = queue.length;
    for (const item of items) {
      let list = constraints.get(item.name);
      if (!list) {
