const { satisfies, compare } = require('./src/semver');
const assert = require('assert/strict');

// 1. Numeric ordering across widths
assert.deepEqual(resolve({a:{'9.0.0':{},'10.0.0':{},'2.0.0':{}}}, {a:'*'}), {a:'10.0.0'});

// 2. Backtracking must undo stale constraints (false 'no solution' before fix)
const reg = {
  app: { '1.0.0': { lib: '^1.0.0', util: '*' } },
  lib: { '1.2.0': { util: '<2.0.0' }, '1.1.0': { util: '>=2.0.0' } },
  util: { '2.0.0': {}, '1.0.0': {} },
};
assert.deepEqual(resolve(reg, { app: '1.0.0' }), { app:'1.0.0', lib:'1.2.0', util:'1.0.0' });

// 3. Backtrack to most recent choice: root forces retry of an earlier pick
const reg2 = {
  a: { '1.0.0': { b: '*', c: '*' } },
  b: { '2.0.0': { c: '<1.5.0' }, '1.0.0': {} },
  c: { '2.0.0': {}, '1.0.0': {} },
};
assert.deepEqual(resolve(reg2, { a: '*' }), { a:'1.0.0', b:'2.0.0', c:'1.0.0' });

// 4. Cycle
const reg3 = {
  x: { '1.0.0': { y: '^1.0.0' }, '2.0.0': { y: '^1.0.0' } },
  y: { '1.0.0': { x: '^2.0.0' } },
};
assert.deepEqual(resolve(reg3, { x: '*' }), { x:'2.0.0', y:'1.0.0' });

// 5. Long chain (5000) — no recursion, no iteration cap
const reg4 = {};
for (let i = 0; i < 5000; i++) reg4['p'+i] = { '1.0.0': { ['p'+(i+1)]: '*' } };
reg4['p5000'] = { '1.0.0': {} };
const r5 = resolve(reg4, { p0: '*' });
assert.equal(Object.keys(r5).length, 5001);

// 6. Unsatisfiable -> null; missing package -> null
assert.equal(resolve({a:{'1.0.0':{}}}, {a:'^2.0.0'}), null);
assert.equal(resolve({}, {ghost:'*'}), null);
assert.equal(resolve({a:{'1.0.0':{b:'^1.0.0'}}}, {a:'*'}), null);

// 7. Empty root
assert.deepEqual(resolve({}, {}), {});

// 8. Caret zero-major semantics
assert.equal(satisfies('0.2.5', '^0.2.0'), true);
assert.equal(satisfies('0.3.0', '^0.2.0'), false);
assert.equal(satisfies('1.0.0', '^0.2.0'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('1.9.9', '^1.2.3'), true);
assert.equal(satisfies('2.0.0', '^1.2.3'), false);
assert.equal(satisfies('1.5.0', '~1.4.0'), false);
assert.equal(satisfies('1.4.9', '~1.4.0'), true);

// 9. Eager validation of unreachable entries
assert.throws(() => resolve({a:{'1.0.0':{}}, bad:{'oops':{}}}, {a:'*'}), TypeError);
assert.throws(() => resolve({a:{'1.0.0':{}}, bad:{'1.0.0':{x:'>>1'}}}, {a:'*'}), TypeError);
assert.throws(() => resolve({a:{'1.0.0':{}}}, {a:''}), TypeError);
assert.throws(() => resolve([], {}), TypeError);

// 10. First-found determinism: highest version satisfying constraints so far
const reg10 = {
  top: { '1.0.0': { dep: '<1.5.0' } },
  dep: { '2.0.0': {}, '1.4.0': {}, '1.3.0': {} },
};
